var found = false;
var input = new tw.object.Map();
input.put("odcRequest",tw.local.odcRequest);
input.put("routingDetails",tw.local.routingDetails);
input.put("processInitiator",tw.system.user.name);

 
tw.local.processName = tw.epv.ODCProcessName.closure+"";
var process = tw.system.startProcessByName(tw.local.processName, input, true);
			
	if(process != null)
	{
		tw.local.instanceID = process.id.split(".")[1];
		while(found == false)
		{
			java.lang.Thread.sleep(3000);
			var tasks = process.tasks.length-1;
			if(process.tasks[tasks].subject == ""+tw.epv.stepName.ACT1Closure)
			{
				tw.local.taskID = process.tasks[tasks].id.split(".")[1];
				found = true;
			}
		}
	}

tw.local.processStarted= true;

var found = false;
var input = new tw.object.Map();
input.put("odcRequest",tw.local.odcRequest);
input.put("routingDetails",tw.local.routingDetails);

tw.local.processName = tw.epv.ODCProcessName.reversal+"";
var process = tw.system.startProcessByName(tw.local.processName, input, true);
			
	if(process != null)
	{
		tw.local.instanceID = process.id.split(".")[1];
